local GrowthFundMainLineDialog = Class('GrowthFundMainLineDialog')
---@type SDKService
local SDKService = import('Game.Entry.SDKService')
local KTool = CS.Engine.Lib.KTool
local CellPath = "Game.UI.ResidentEvent.GrowthFundMainLineCell"
local ItemCell = "Cell"
local UIModule = CS.Engine.UI.UIModule
function GrowthFundMainLineDialog:__init()
    self.tagEnv = {}
    self.rewardVos = {}
    self.cellAnimMap_ = {}
end

function GrowthFundMainLineDialog:__delete()
    self.tagEnv = nil
    self.rewardVos = nil
    self.cellAnimMap_ = nil
end

function GrowthFundMainLineDialog:Awake()
    self.__EventSdkEvent = Events.AddListener(Constants.EventNames.EVENT_SDK, Bind(self, self.OnEventSdkEvent))
    self:AddUIClick()
    self:InitContent()
end

function GrowthFundMainLineDialog:InitContent()
    local allVos = CfUtils.GetCf(AutoIds.IdSetting4010, "GrowthFundMainLineRewardVo", true)
    local data = {}
    if not isNull(allVos) and table.count(allVos) > 0 then
        for i, v in pairs(allVos) do
            if not data[v.stageId] then
                data[v.stageId] = {}
            end
            table.insert(data[v.stageId],v)
        end
    end
    for i, v in pairs(data) do
        table.insert(self.rewardVos,v)
    end
    table.sort(self.rewardVos,function(a,b)
        local stageIda = a[1].stageId
        local stageIdb = b[1].stageId
        return stageIda < stageIdb
    end)

    local initTagCount = 1
    KTool.SetActive(self.BtnTag.gameObject,false)
    if self.BtnTag then
        local env = CfUtils.GetLuaScr(self.BtnTag,"Game.UI.ResidentEvent.GrowthFundMainLineTagCell")
        if env then
            env:SetLevelAndCallBack(1,Bind(self,self.OnTagCellClick))
            self.tagEnv[1] = env
        end
    end


    for i, v in pairs(self.rewardVos) do
        local data = v[table.count(v)]
        local isUnLock = GameUtils.IsUnlockedSingle(data.unlockType, data.unlockId)
        if isUnLock then
            initTagCount = initTagCount + 1
            if initTagCount > table.count(self.rewardVos) then
                initTagCount = table.count(self.rewardVos)
            end
        end
    end

    if initTagCount > 1 then
        for i = 2, initTagCount do
            local tagGo = CS.UnityEngine.GameObject.Instantiate(self.BtnTag.gameObject)
            tagGo.name = self.BtnTag.name..i
            KTool.SetActive(tagGo,false)
            KTool.SetParent(tagGo,self.PeriodTag.gameObject,false)
            if tagGo then
                local env = CfUtils.GetLuaScr(tagGo,"Game.UI.ResidentEvent.GrowthFundMainLineTagCell")
                if env then
                    env:SetLevelAndCallBack(i,Bind(self,self.OnTagCellClick))
                    self.tagEnv[i] = env
                end
            end
        end
    end
end

function GrowthFundMainLineDialog:AddUIClick()
    SetButtonAction(self.BtnCost.gameObject,Bind(self,self.OnBtnBuyClick))
    SetButtonAction(self.BtnOnekeyDraw.gameObject,Bind(self,self.OnBtnOneKeyDrawClick))
end

function GrowthFundMainLineDialog:Refresh(data)
    if not data then return end
    xRecord.record('4-004')
    self.data = data
    GameUtils.Request(Interfaces.OverseaGrowthFund,{},function(request,response)
        if  checkInt(response.errCode) == 0  then
            self.serverData = response.data
            self:ConvertPrices(self.serverData.growthFundBuyInfo)
            self:InitServerData()
            self:RequestShow()
        end
    end )
end

function GrowthFundMainLineDialog:InitServerData()
    local data = self.serverData.growthFundInfo
    local sortData = {}
    for i, v in pairs(data) do
        v.id = i
        table.insert(sortData,v)
    end
    table.sort(sortData,function(a,b) return a.id < b.id end)
    self.serverData.growthFundInfo = sortData
end

function GrowthFundMainLineDialog:RequestShow()
    local id = self:GetCanDrawRewardId()
    local index = self:IdToIndex(id) or 1
    self.tagEnv[index]:SetSelectState(true)
    self:OnTagCellClick(index)
end

function GrowthFundMainLineDialog:IdToIndex(id)
    for i, v in pairs(self.rewardVos) do
        if v[1].stageId == id then
            return i
        end
    end
    return 1
end

function GrowthFundMainLineDialog:OnTagCellClick(i)
    if self.preSelect and self.preSelect == i then
        return
    end
    local lastSelect = self.preSelect
    if lastSelect and lastSelect ~= i then
        self.tagEnv[lastSelect]:SetSelectState(false)
    end
    self.preSelect = i
    self:RefreshShow()
    self:RefreshIsBuy()
    self:SetRewardAndPriceShow()
end

function GrowthFundMainLineDialog:SetRewardAndPriceShow()
    local rewardNum,allRewardNum = self:CalculationRewardNum()
    CfUtils.FillText(self.RewardNum,localize("购买后可获得猫眼石\n共_num_",{_num_ = rewardNum}))
    local priceInfo = self.serverData.growthFundBuyInfo[self.preSelect]
    local isDirect = (not next(priceInfo.prices))
    CfUtils.SetActive(self.ImgIcon,not isDirect)
    if isDirect then
        CfUtils.FillText(self.Price,CfUtils.GetDisplayPrice(priceInfo.price , priceInfo.channelProductId))
    else
        local goodDojo = table.takeFirst(table.values(priceInfo.prices))
        local goodId = goodDojo.currency
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodId)
        if not isNull(goodsVo) then
            CfUtils.FillImage(self.ImgIcon,goodsVo.photoPath)
        end
        CfUtils.FillText(self.Price,goodDojo.current)
    end

    CfUtils.FillText(self.AllRewardNum,string.format("x %s",allRewardNum))
end

function GrowthFundMainLineDialog:CalculationRewardNum()
    local chargeRewardNum = 0
    local freeRewardNum = 0
    for i, v in pairs(self.rewardVos[self.preSelect]) do
        freeRewardNum = freeRewardNum + v.freeRewardNum
        chargeRewardNum = chargeRewardNum + v.ChargeRewardNum
    end
    local allRewardNum = freeRewardNum + chargeRewardNum
    return chargeRewardNum,allRewardNum
end

function GrowthFundMainLineDialog:RefreshIsBuy()
    local isBuy = self:IsBuy()
    KTool.SetActive(self.UnlockMethod.gameObject,not isBuy)
    KTool.SetActive(self.ImgLcok.gameObject,not isBuy)
    KTool.SetActive(self.TextBuy.gameObject, isBuy)
    KTool.SetActive(self.UIFX_UnlockMethod.gameObject, not isBuy)
end

function GrowthFundMainLineDialog:IsBuy()
    local isBuy = false
    if self.serverData.growthFundBuyInfo[self.preSelect] and self.serverData.growthFundBuyInfo[self.preSelect].isBuy > 0 then
        isBuy = true
    end
    return isBuy
end

function GrowthFundMainLineDialog:RefreshShow()
    self.curData = self:GetDataByIndex()
    if self.ScrollView then
        if not self.ScrollView.IsListViewInit then
            self.ScrollView:InitListView(#self.curData.staticData, Bind(self, self.OnRefreshCellIndex))
        else
            GameUtils.ReloadData(self.ScrollView, #self.curData.staticData)
        end
    end
    self:RefreshTagRedPoint()
end

function GrowthFundMainLineDialog:OnRefreshCellIndex(listView,index)
    if index < 0 or index >= #self.curData.staticData then
        return
    end
    local cell = listView:NewListViewItem(ItemCell)
    local tableCellEnv = CfUtils.GetLuaScr(cell, CellPath)
    local isBuy = self:IsBuy()
    tableCellEnv:SetCallBackAndIndex(Bind(self,self.OnDrawRewardClick),index + 1)
    tableCellEnv:RefreshShow(self.curData.staticData[index + 1],self.curData.serverData,isBuy)
    local luaIndex = index + 1
    if not self.cellAnimMap_[luaIndex] then
        self.cellAnimMap_[luaIndex] = true
        tableCellEnv:PlayAnimByEnter(index)
    else
        tableCellEnv:PlayAnimByShowed()
    end
    return cell
end

function GrowthFundMainLineDialog:OnDrawRewardClick(id, type)
    GameUtils.Request(Interfaces.OverseaGrowthFundDraw,{rewardId = id,rewardType = type},function(request,response)
        if  checkInt(response.errCode) == 0  then
            local rewards = response.data.rewards
            self:SetSingData(id, type)
            if #rewards > 0 then
                GoodsUtils.DrawRewards(rewards)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
            end
            local isHave = self:GetCanDrawRewardId()
            GameUtils.UpdateServerRedPointData({ unGrowthFund = isNull(isHave) and -1 or 0})
            self:RefreshShow()
        end
    end)
end

function GrowthFundMainLineDialog:SetSingData(id , type)
    local curData = self.serverData.growthFundInfo[self.preSelect]
    local getData = type == 0 and curData.freeRewardStatus or curData.payRewardStatus
    if isNotNull(getData) then
        getData[tostring(id)] = 2
    end
end

function GrowthFundMainLineDialog:GetDataByIndex()
    local data = {}
    for i, v in pairs(self.rewardVos) do
        if i == self.preSelect then
            data = { staticData = v,serverData = self.serverData.growthFundInfo[i] }
            break
        end
    end
    return data
end


function GrowthFundMainLineDialog:OnDestroy()
    self.rewardVos = nil
    self.data = nil
    self.controller = nil--luabehaviour 中CSharp对象
    if self.__EventSdkEvent then
        Events.RemoveListener(Constants.EventNames.EVENT_SDK, self.__EventSdkEvent)
        self.__EventSdkEvent = nil
    end
    self:Delete()
end

function GrowthFundMainLineDialog:OnBtnOneKeyDrawClick()
    local isHave = self:IsAllHaveRewardToGet()
    if isHave then
        GameUtils.Request(Interfaces.OverseaGrowthFundOneKeyDraw,nil,function(request,response)
            if  checkInt(response.errCode) == 0  then
                local rewards = response.data.rewards
                if #rewards > 0 then
                    GoodsUtils.DrawRewards(rewards)
                    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
                end
                self:SetData()

                local isHave = self:GetCanDrawRewardId()
                GameUtils.UpdateServerRedPointData({ unGrowthFund = isNull(isHave) and -1 or 0})

                self:RefreshShow()
            end
        end)
    else
        GameUtils.Toast(localize("暂无可领取的奖励"))
    end
end

function GrowthFundMainLineDialog:RefreshTagRedPoint()
    for i, v in pairs(self.tagEnv) do
        local isHave = self:IsHaveRewardToGet(i)
        self.tagEnv[i]:RefreshRedPoint(isHave)
    end
    local count = self:GetTagUnLockCount()
    if count ~= 0 then
        for i = 1, count do
            KTool.SetActive(self.tagEnv[i].controller.gameObject,true)
        end
    end
end

function GrowthFundMainLineDialog:IsHaveRewardToGet(index)
    local freeRewardStates = self.serverData.growthFundInfo[index].freeRewardStatus
    for i, v in pairs(freeRewardStates) do
        if v == Constants.GetStatus.Can then
            return true
        end
    end
    local chargeRewardState = self.serverData.growthFundInfo[index].payRewardStatus
    for i, v in pairs(chargeRewardState) do
        if v == Constants.GetStatus.Can then
            return true
        end
    end
    return false
end

function GrowthFundMainLineDialog:SetData()
    local count = self:GetTagUnLockCount()
    if count == 0 then
        count = 1
    end

    for k, v in pairs(self.serverData.growthFundInfo) do
        if k <= count  then
            local freeRewardState = v.freeRewardStatus
            for i, j in pairs(freeRewardState) do
                if j == Constants.GetStatus.Can then
                    freeRewardState[tostring(i)] = 2
                end
            end
            local chargeRewardState = v.payRewardStatus
            for i, j in pairs(chargeRewardState) do
                if j == Constants.GetStatus.Can then
                    chargeRewardState[tostring(i)] = 2
                end
            end
        end
    end
end

function GrowthFundMainLineDialog:GetTagUnLockCount()
    local unLockTag = 0
    for i = 1, #self.tagEnv do
        local freeData = self.serverData.growthFundInfo[i].freeRewardStatus
        local lockCount = 0
        if i == 1 then
            for k, v in pairs(freeData) do
                if v == Constants.GetStatus.Has then
                    lockCount = lockCount + 1
                end
            end
            if lockCount == table.count(freeData) then
                unLockTag = 2
            else
                break
            end
        else
            freeData = self.serverData.growthFundInfo[i - 1].freeRewardStatus
            for k, v in pairs(freeData) do
                if v == Constants.GetStatus.Has then
                    lockCount = lockCount + 1
                end
            end
            if lockCount == table.count(freeData) then
                unLockTag = i
            else
                break
            end
        end
    end

    return unLockTag

end

function GrowthFundMainLineDialog:GetCanDrawRewardId()
    local count = self:GetTagUnLockCount()
    if count == 0 then
        return nil
    end
    for k, v in pairs(self.serverData.growthFundInfo) do
        if k > count  then
            return nil
        end
        local freeRewardState = v.freeRewardStatus
        for i, j in pairs(freeRewardState) do
            if j == Constants.GetStatus.Can then
                return tonumber(v.id)
            end
        end
        local chargeRewardState = v.payRewardStatus
        for i, j in pairs(chargeRewardState) do
            if j == Constants.GetStatus.Can then
                return tonumber(v.id)
            end
        end
    end
    return nil
end

function GrowthFundMainLineDialog:IsAllHaveRewardToGet()
    local count = self:GetTagUnLockCount()
    if count == 0 then
        count = 1
    end
    for k, v in pairs(self.serverData.growthFundInfo) do
        if k > count  then
            return false
        end
        local freeRewardState = v.freeRewardStatus
        for i, j in pairs(freeRewardState) do
            if j == Constants.GetStatus.Can then
                return true
            end
        end
        local chargeRewardState = v.payRewardStatus
        for i, j in pairs(chargeRewardState) do
            if j == Constants.GetStatus.Can then
                return true
            end
        end
    end
    return false
end

function GrowthFundMainLineDialog:OnBtnBuyClick()
    self:OnBuy()
end

function GrowthFundMainLineDialog:OnBuy()
    xRecord.record('4-005')
    local payInfo = self.serverData.growthFundBuyInfo[self.preSelect]
    if payInfo then
        local isDirect = (not next(payInfo.prices))
        if isDirect then
            SDKService:GetInstance():PayMoney({
                productId = payInfo.productId,
                channelProductId = payInfo.channelProductId,
                productDesc = localize("成长基金"),
                payAmount = payInfo.price,
                data = payInfo
            })
        else
            local goodDojo = table.takeFirst(table.values(payInfo.prices))
            ---@type ServerDifferenceMgr
            local ServerDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()
            local current = goodDojo.current
            ServerDifferenceMgr:WrapPrimaryCurrencyBuy({
                currency = goodDojo.currency,
                current =  current,
            }, function(isSuccess)
                isSuccess = checkBool(isSuccess)
                if not isSuccess then
                    return
                end
                GameUtils.Request(Interfaces.GrowthFundCurrencyBuy,{productId = payInfo.productId ,num = 1,currency = goodDojo.currency},function(request,response)
                    if checkNumber(response.errCode) == 0 then
                        GoodsUtils.ConsumeGoods({ {goodsId = goodDojo.currency, num = goodDojo.current, productId = checkNumber(payInfo.productId)} } , true)
                        GameUtils.Request(Interfaces.OverseaGrowthFund,{},function(request,response)
                            if  checkInt(response.errCode) == 0  then
                                self.serverData = response.data
                                self:ConvertPrices(self.serverData.growthFundBuyInfo)
                                self:InitServerData()
                                self:RefreshShow()
                                self:RefreshIsBuy()
                            end
                        end)
                    end
                end)
            end)
        end
    end
end

--支付成功
function GrowthFundMainLineDialog:OnEventSdkEvent(parameters)
    --- sdk pay succeed
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
        GameUtils.Request(Interfaces.OverseaGrowthFund,{},function(request,response)
            if  checkInt(response.errCode) == 0  then
                self.serverData = response.data
                self:ConvertPrices(self.serverData.growthFundBuyInfo)
                self:InitServerData()
                self:RefreshShow()
                self:RefreshIsBuy()
            end
        end
        )
    end
end

function GrowthFundMainLineDialog:ConvertPrices(data)
    if not data then return end
    --local data = {prices = { ["300002"] = { current = 30,original = 600 } } }
    for i, v in pairs(data) do
        if not isNull(v.prices) and next(v.prices) then
            local t = {}
            for i, j in pairs(v.prices) do
                local tmp = {}
                tmp.current = j.current
                tmp.original = j.original
                tmp.currency = tonumber(i)
                table.insert(t, tmp)
            end
            v.prices = t
        end
    end

end

return GrowthFundMainLineDialog